  const category: BlogCategory = 'LLM Tuning';

  const fullFinetuningExample = `from transformers import (
    Trainer,
    TrainingArguments,
    AutoModelForCausalLM,
    AutoTokenizer
)

# Full Fine-tuning Setup
def setup_full_finetuning(
    model_name: str,
    train_dataset,
    output_dir: str
):
    # Load model and tokenizer
    model = AutoModelForCausalLM.from_pretrained(
        model_name,
        device_map="auto"
    )
    tokenizer = AutoTokenizer.from_pretrained(model_name)

    # Configure training arguments
    training_args = TrainingArguments(
        output_dir=output_dir,
        num_train_epochs=3,
        per_device_train_batch_size=4,
        gradient_accumulation_steps=4,
        learning_rate=2e-5,
        weight_decay=0.01,
        warmup_steps=500,
        save_steps=1000,
        logging_steps=100,
    )

    # Initialize trainer
    trainer = Trainer(
        model=model,
        args=training_args,
        train_dataset=train_dataset,
        tokenizer=tokenizer
    )

    return trainer`;

  const loraExample = `from peft import (
    LoraConfig,
    get_peft_model,
    TaskType
)

def setup_lora_finetuning(
    base_model,
    train_dataset,
    output_dir: str
):
    # LoRA configuration
    lora_config = LoraConfig(
        r=16,             # Rank of update matrices
        lora_alpha=32,    # Alpha scaling factor
        target_modules=["q_proj", "v_proj"],
        lora_dropout=0.05,
        bias="none",
        task_type=TaskType.CAUSAL_LM
    )

    # Create PEFT model
    peft_model = get_peft_model(
        base_model,
        lora_config
    )

    # Training arguments
    training_args = TrainingArguments(
        output_dir=output_dir,
        num_train_epochs=3,
        per_device_train_batch_size=8,  # Can be larger than full fine-tuning
        learning_rate=1e-4,
        gradient_accumulation_steps=2
    )

    return peft_model, training_args`;

  const qloraExample = `from peft import (
    prepare_model_for_kbit_training,
    LoraConfig,
    get_peft_model
)
from transformers import BitsAndBytesConfig

def setup_qlora_finetuning(
    model_name: str,
    train_dataset
):
    # Quantization configuration
    bnb_config = BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_compute_dtype=torch.float16,
        bnb_4bit_use_double_quant=True,
        bnb_4bit_quant_type="nf4"
    )

    # Load quantized model
    model = AutoModelForCausalLM.from_pretrained(
        model_name,
        quantization_config=bnb_config,
        device_map="auto"
    )

    # Prepare model for k-bit training
    model = prepare_model_for_kbit_training(model)

    # LoRA configuration for QLoRA
    qlora_config = LoraConfig(
        r=64,
        lora_alpha=16,
        target_modules=["q_proj", "v_proj"],
        lora_dropout=0.1,
        bias="none"
    )

    # Create PEFT model
    peft_model = get_peft_model(model, qlora_config)

    return peft_model`;

