  const ragExample = `from langchain.embeddings import OpenAIEmbeddings
from langchain.vectorstores import Chroma
from langchain.text_splitter import CharacterTextSplitter
from langchain.chains import RetrievalQA

# RAG Implementation Example
def create_rag_system(documents):
    # Split documents into chunks
    text_splitter = CharacterTextSplitter(
        chunk_size=1000,
        chunk_overlap=200
    )
    texts = text_splitter.split_documents(documents)
    
    # Create embeddings and vector store
    embeddings = OpenAIEmbeddings()
    vectorstore = Chroma.from_documents(
        texts,
        embeddings
    )
    
    # Create QA chain
    qa_chain = RetrievalQA.from_chain_type(
        llm=OpenAI(),
        chain_type="stuff",
        retriever=vectorstore.as_retriever()
    )
    
    return qa_chain`;

  const finetuningExample = `from transformers import (
    AutoModelForCausalLM,
    AutoTokenizer,
    TrainingArguments,
    Trainer
)

# Fine-tuning Implementation Example
def setup_finetuning(model_name, dataset):
    # Load model and tokenizer
    model = AutoModelForCausalLM.from_pretrained(
        model_name,
        device_map="auto"
    )
    tokenizer = AutoTokenizer.from_pretrained(model_name)
    
    # Training arguments
    training_args = TrainingArguments(
        output_dir="./results",
        num_train_epochs=3,
        per_device_train_batch_size=4,
        save_steps=10_000,
        save_total_limit=2,
    )
    
    # Initialize trainer
    trainer = Trainer(
        model=model,
        args=training_args,
        train_dataset=dataset,
        tokenizer=tokenizer
    )
    
    return trainer`;

  const hybridExample = `class HybridSystem:
    def __init__(self):
        self.rag_system = create_rag_system(documents)
        self.fine_tuned_model = load_fine_tuned_model()
        
    def process_query(self, query):
        # Check if query needs domain expertise
        if needs_domain_expertise(query):
            # Use fine-tuned model
            return self.fine_tuned_model.generate(query)
        
        # Use RAG for general knowledge
        context = self.rag_system.retrieve(query)
        return self.rag_system.generate(query, context)
        
    def needs_domain_expertise(self, query):
        # Implement logic to determine query type
        domain_keywords = ["technical", "specialized", ...]
        return any(kw in query.lower() for kw in domain_keywords)`;

