  const dataProcessingExample = `import pandas as pd
from datasets import Dataset
from typing import List, Dict

class DatasetProcessor:
    def __init__(self):
        self.validation_rules = {
            'min_length': 50,
            'max_length': 2048,
            'required_fields': ['text', 'label']
        }
    
    def process_raw_data(
        self,
        data: List[Dict],
        format_type: str = 'instruction'
    ) -> Dataset:
        # Convert to DataFrame for easy processing
        df = pd.DataFrame(data)
        
        # Clean and validate
        df = self.clean_data(df)
        df = self.validate_entries(df)
        
        # Format based on type
        if format_type == 'instruction':
            df = self.format_instruction_data(df)
        elif format_type == 'conversation':
            df = self.format_conversation_data(df)
            
        # Convert to HuggingFace dataset
        dataset = Dataset.from_pandas(df)
        
        return dataset
    
    def clean_data(self, df: pd.DataFrame) -> pd.DataFrame:
        # Remove duplicates
        df = df.drop_duplicates(subset=['text'])
        
        # Remove empty entries
        df = df.dropna(subset=['text'])
        
        # Clean text
        df['text'] = df['text'].apply(self.clean_text)
        
        return df
    
    def clean_text(self, text: str) -> str:
        # Basic text cleaning
        text = text.strip()
        text = ' '.join(text.split())  # Normalize whitespace
        text = text.replace('\\n', ' ')
        return text`;

  const dataFormattingExample = `class DataFormatter:
    def format_instruction_data(
        self,
        instruction: str,
        input_text: str = "",
        output: str = ""
    ) -> Dict:
        return {
            "instruction": instruction,
            "input": input_text,
            "output": output
        }
    
    def format_conversation_data(
        self,
        messages: List[Dict]
    ) -> Dict:
        return {
            "messages": messages,
            "system": "You are a helpful assistant."
        }
    
    def create_dataset_entry(
        self,
        data: Dict,
        format_type: str
    ) -> Dict:
        if format_type == "instruction":
            return {
                "text": f"""### Instruction:
{data['instruction']}

### Input:
{data['input']}

### Response:
{data['output']}"""
            }
        elif format_type == "conversation":
            messages = "\\n".join([
                f"{m['role']}: {m['content']}"
                for m in data['messages']
            ])
            return {
                "text": f"""### System:
{data['system']}

### Conversation:
{messages}"""
            }`;

