  const optimizationExample = `import torch
from transformers import AutoModelForCausalLM
from optimum.onnx import OnnxConfig, OnnxRuntime
from optimum.bettertransformer import BetterTransformer

class ModelOptimizer:
    def __init__(
        self,
        model_path: str,
        optimization_level: str = "balanced"
    ):
        self.model = AutoModelForCausalLM.from_pretrained(
            model_path
        )
        self.level = optimization_level
    
    def optimize_model(self):
        # 1. Apply BetterTransformer optimizations
        self.model = BetterTransformer.transform(
            self.model
        )
        
        # 2. Quantize model
        if self.level == "memory":
            self.quantize_model()
        
        # 3. Export to ONNX
        self.export_to_onnx()
        
        return self.model
    
    def quantize_model(self):
        # Dynamic quantization
        self.model = torch.quantization.quantize_dynamic(
            self.model,
            {torch.nn.Linear},
            dtype=torch.qint8
        )
    
    def export_to_onnx(self):
        # Create ONNX config
        onnx_config = OnnxConfig.from_model_config(
            self.model.config
        )
        
        # Export model
        onnx_path = "optimized_model.onnx"
        OnnxRuntime.export(
            self.model,
            onnx_config,
            output=onnx_path
        )
        
        return onnx_path`;

