  const deploymentExample = `from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import torch

class CodeGeneration(BaseModel):
    prompt: str
    language: str
    max_length: int = 1024
    temperature: float = 0.7

class CodeModelServer:
    def __init__(
        self,
        model_path: str
    ):
        self.app = FastAPI()
        self.setup_model(model_path)
        self.setup_routes()
    
    def setup_model(self, model_path: str):
        self.model = AutoModelForCausalLM.from_pretrained(
            model_path,
            device_map="auto",
            torch_dtype=torch.float16
        )
        self.tokenizer = CodeLlamaTokenizer.from_pretrained(
            model_path
        )
    
    def setup_routes(self):
        @self.app.post("/generate")
        async def generate_code(request: CodeGeneration):
            try:
                # Prepare prompt
                prompt = self.prepare_prompt(
                    request.prompt,
                    request.language
                )
                
                # Generate code
                generated = await self.generate(
                    prompt,
                    request.max_length,
                    request.temperature
                )
                
                # Post-process
                processed = self.post_process(
                    generated,
                    request.language
                )
                
                return {
                    "code": processed,
                    "language": request.language
                }
                
            except Exception as e:
                raise HTTPException(
                    status_code=500,
                    detail=str(e)
                )
    
    async def generate(
        self,
        prompt: str,
        max_length: int,
        temperature: float
    ) -> str:
        inputs = self.tokenizer(
            prompt,
            return_tensors="pt"
        ).to(self.model.device)
        
        with torch.no_grad():
            outputs = self.model.generate(
                **inputs,
                max_length=max_length,
                temperature=temperature,
                do_sample=True
            )
        
        return self.tokenizer.decode(
            outputs[0],
            skip_special_tokens=True
        )`;

