import React from 'react';
import "../../../styles/blogs/blog-base-style.css";
import BlogTemplate from '../../../components/blogs/BlogTemplate';
import { BlogSection, InfoBox } from '../../../components/blogs/BlogComponents';
import blogMetadataRaw from '../../../data/blog_metadata.json';
import {BlogCategory} from "../../../data/types";

// TypeScript interface for blog metadata
interface BlogMetadata {
  title: string;
  url: string;
  date: string;
  source: string;
  category: string;
  summary?: string;
  generated_content?: string;
  keywords?: string[];
}

// Type assertion for the imported JSON
const blogMetadata = blogMetadataRaw as BlogMetadata[];

const LatestBlogs: React.FC = () => {
  const tableOfContents = [
    { id: 'introduction', title: 'Introduction' },
    { id: 'latest-updates', title: 'Latest Updates' },
    { id: 'by-category', title: 'Blogs by Category' }
  ];

  const category: BlogCategory = 'Tools & Frameworks';

  // Group blogs by category
  const blogsByCategory = blogMetadata.reduce((acc, blog) => {
    if (!acc[blog.category]) {
      acc[blog.category] = [];
    }
    acc[blog.category].push(blog);
    return acc;
  }, {} as Record<string, typeof blogMetadata>);

  return (
    <BlogTemplate
      title="Latest AI & LLM Blog Updates"
      date="April 17, 2025"
      readTime="5 min"
      category={category}
      tableOfContents={tableOfContents}
    >
      <BlogSection id="introduction" title="Introduction">
        <p>
          A curated collection of the latest blog posts and articles about AI, Large Language Models (LLMs),
          and related technologies. This list is regularly updated to include new insights, tutorials,
          and developments from leading organizations and experts in the field.
        </p>
      </BlogSection>

      <BlogSection id="latest-updates" title="Latest Updates">
        <div className="space-y-2">
          {blogMetadata.slice(0, 10).map((blog, index) => (
            <div key={index} className="py-1">
              <a 
                href={blog.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-blue-600 hover:text-blue-800 hover:underline"
              >
                {blog.title}
              </a>
              <span className="text-sm text-gray-500 ml-2">
                ({blog.source})
              </span>
            </div>
          ))}
        </div>
      </BlogSection>

      <BlogSection id="by-category" title="Blogs by Category">
        {Object.entries(blogsByCategory).map(([categoryName, blogs]) => (
          <div key={categoryName} className="mb-8">
            <h3 className="text-lg font-semibold mb-3 text-gray-800">
              {categoryName}
            </h3>
            <div className="space-y-2 ml-4">
              {blogs.map((blog, index) => (
                <div key={index} className="py-1">
                  <a 
                    href={blog.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-blue-600 hover:text-blue-800 hover:underline"
                  >
                    {blog.title}
                  </a>
                  <span className="text-sm text-gray-500 ml-2">
                    ({blog.source})
                  </span>
                </div>
              ))}
            </div>
          </div>
        ))}

        <InfoBox type="tip" title="Stay Updated">
          <p>
            This list is regularly updated with new content. Bookmark this page to stay
            informed about the latest developments in AI and LLM technologies.
          </p>
        </InfoBox>
      </BlogSection>
    </BlogTemplate>
  );
};

export default LatestBlogs;